    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$OperationsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$OperationsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$OperationsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                Value<String> kind = const Value.absent(),
                Value<int> effectiveDate = const Value.absent(),
                Value<int> amountMinor = const Value.absent(),
                Value<String> currencyCode = const Value.absent(),
                Value<String?> bucket = const Value.absent(),
                Value<int> accountId = const Value.absent(),
                Value<int?> categoryId = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
              }) => OperationsCompanion(
                id: id,
                kind: kind,
                effectiveDate: effectiveDate,
                amountMinor: amountMinor,
                currencyCode: currencyCode,
                bucket: bucket,
                accountId: accountId,
                categoryId: categoryId,
                createdAt: createdAt,
                updatedAt: updatedAt,
              ),
          createCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                required String kind,
                required int effectiveDate,
                required int amountMinor,
                required String currencyCode,
                Value<String?> bucket = const Value.absent(),
                required int accountId,
                Value<int?> categoryId = const Value.absent(),
                required DateTime createdAt,
                required DateTime updatedAt,
              }) => OperationsCompanion.insert(
                id: id,
                kind: kind,
                effectiveDate: effectiveDate,
                amountMinor: amountMinor,
                currencyCode: currencyCode,
                bucket: bucket,
                accountId: accountId,
                categoryId: categoryId,
                createdAt: createdAt,
                updatedAt: updatedAt,
